<div id="calc-determinante-gauss" class="det-tutor-container"><!-- Cabecera -->
<div style="background: #e67e22; color: white; padding: 15px; text-align: center;">
<h2 style="margin: 0; text-shadow: 1px 1px 2px rgba(0,0,0,0.2);"><img src="{{context_path}}/content/resources/202604291703031226YD/yoneco_1.png" width="60" height="60" alt="" style="vertical-align: middle;" /> Tutor Interactivo: Determinante por Gauss</h2>
</div>
<!-- Panel de Control -->
<div style="padding: 15px 20px; background: #fdf2e9; border-bottom: 1px solid #edbb99; display: flex; flex-wrap: wrap; gap: 20px; justify-content: space-between; align-items: center;">
<div style="display: flex; gap: 15px; align-items: center;"><label style="font-weight: bold; color: #444;">Dimensión:</label><select id="det-order" style="padding: 5px; border-radius: 4px; border: 1px solid #d35400; outline: none;">
<option value="3" selected="selected">3x3</option>
<option value="4">4x4</option>
<option value="5">5x5</option>
</select></div>
<div style="display: flex; gap: 15px; align-items: center;"><label style="font-weight: bold; color: #444;">Números:</label> <label><input type="radio" name="det-tipo" value="nat" checked="checked" /> Naturales</label> <label><input type="radio" name="det-tipo" value="ent" /> Enteros</label></div>
<div style="display: flex; gap: 15px; align-items: center; border-left: 2px solid #edbb99; padding-left: 15px;"><label style="font-weight: bold; color: #c0392b;">Modo:</label> <label><input type="radio" name="det-dif" value="normal" checked="checked" /> Fácil (🐔)</label> <label><input type="radio" name="det-dif" value="pro" /> <b>Pro (Fracciones)</b></label></div>
<div><button onclick="detGenerar()" class="det-btn-main">Generar Nuevo</button></div>
<div style="font-size: 0.95em; color: #666; max-width: 100%; width: 100%; border-top: 1px dashed #edbb99; padding-top: 10px;"><i><b>Nota importante:</b> Para no alterar el valor del determinante, usa estrictamente operaciones del tipo <b>F<sub>objetivo</sub> → F<sub>objetivo</sub> + k · F<sub>pivote</sub></b>. Si el pivote no es 1, necesitarás usar fracciones (ej: -1/2).</i></div>
</div>
<div style="padding: 20px; display: flex; flex-direction: column; align-items: center;"><!-- Determinante Principal -->
<div style="margin-bottom: 25px; text-align: center;">
<h3 style="color: #d35400; margin-top: 0;">Determinante Actual |A|</h3>
<div id="det-matrix-display" style="display: inline-grid; gap: 15px 20px; position: relative; padding: 10px 25px; font-size: 1.3em; font-family: monospace; background: #fff; align-items: center; border-radius: 8px;"><!-- Decoración -->
<div style="position: absolute; top: -5px; bottom: -5px; left: 0; width: 4px; border-left: 3px solid #333;"><br /></div>
<div style="position: absolute; top: -5px; bottom: -5px; right: 0; width: 4px; border-right: 3px solid #333;"><br /></div>
<!-- Celdas generadas dinámicamente --></div>
</div>
<!-- Contenedor dinámico de pasos -->
<div id="det-steps-container" style="width: 100%; display: flex; flex-direction: column; align-items: center;"></div>
</div>
</div>
<p>
<script>
    // --- MOTOR DE FRACCIONES EXACTAS ---
    function gcd(a, b) {
        a = Math.abs(a); b = Math.abs(b);
        while (b) { let t = b; b = a % b; a = t; }
        return a || 1;
    }
    function simplify(n, d) {
        if (n === 0) return {n: 0, d: 1};
        if (d < 0) { n = -n; d = -d; }
        let g = gcd(n, d);
        return {n: n / g, d: d / g};
    }
    function fAdd(a, b) { return simplify(a.n * b.d + b.n * a.d, a.d * b.d); }
    function fSub(a, b) { return simplify(a.n * b.d - b.n * a.d, a.d * b.d); }
    function fMul(a, b) { return simplify(a.n * b.n, a.d * b.d); }
    function fDiv(a, b) { return simplify(a.n * b.d, a.d * b.n); }
    function fEqual(a, b) { return a.n * b.d === b.n * a.d; }
    function fIsZero(a) { return a.n === 0; }

    function parseFracObj(valStr) {
        if(!valStr || valStr.trim() === '') return null;
        valStr = valStr.replace(/\s+/g, '').replace(',', '.');
        if(valStr.includes('/')) {
            let parts = valStr.split('/');
            if(parts.length !== 2) return null;
            let num = parseInt(parts[0]), den = parseInt(parts[1]);
            if(isNaN(num) || isNaN(den) || den === 0) return null;
            return simplify(num, den);
        }
        let val = parseFloat(valStr);
        if(isNaN(val)) return null;
        let str = val.toString();
        if (!str.includes('.')) return {n: parseInt(val), d: 1};
        let decs = str.split('.')[1].length;
        let d = Math.pow(10, decs);
        return simplify(Math.round(val * d), d);
    }

    function formatFracVisual(f) {
        if (f.n === 0) return "0";
        if (f.d === 1) return f.n.toString();
        let sign = f.n < 0 ? "-" : "";
        return `${sign}<div class="frac-css"><span class="fnum">${Math.abs(f.n)}</span><span class="fdn">${f.d}</span></div>`;
    }

    // --- VARIABLES GLOBALES Y ESTADO ---
    let detN = 3;
    let detMatrix = []; 
    let currentPivotCol = 0;
    let rowsCompletedInStep = 0;

    // --- GENERACIÓN SEGURA DE MATRIZ ---
    function detGenerar() {
        detN = parseInt(document.getElementById('det-order').value);
        let isNat = document.querySelector('input[name="det-tipo"]:checked').value === 'nat';
        let isPro = document.querySelector('input[name="det-dif"]:checked').value === 'pro';

        let valid = false;
        let mat = [];

        while(!valid) {
            mat = Array(detN).fill().map(()=>Array(detN).fill({n:0, d:1}));

            if (!isPro) {
                // MODO NORMAL: Se asegura de generar solo enteros en las operaciones
                for(let i=0; i<detN; i++){
                    for(let j=i; j<detN; j++){
                        let val = isNat ? Math.floor(Math.random() * 4) + 1 : Math.floor(Math.random() * 7) - 3;
                        if(i === j && val === 0) val = isNat ? 1 : (Math.random()>0.5 ? 1 : -1);
                        mat[i][j] = {n: val, d: 1};
                    }
                }
                for(let j=0; j<detN-1; j++) {
                    for(let i=j+1; i<detN; i++) {
                        let k = isNat ? Math.floor(Math.random() * 3) : Math.floor(Math.random() * 5) - 2;
                        if(k !== 0) {
                            for(let c=0; c<detN; c++) {
                                mat[i][c] = fAdd(mat[i][c], fMul({n:k, d:1}, mat[j][c]));
                            }
                        }
                    }
                }
                valid = true;
            } else {
                // MODO PRO: Genera matriz aleatoria (Forzará fracciones)
                for(let i=0; i<detN; i++){
                    for(let j=0; j<detN; j++){
                        // Rango más corto para que las fracciones no se vuelvan gigantescas
                        let val = isNat ? Math.floor(Math.random() * 3) + 1 : Math.floor(Math.random() * 7) - 3;
                        if(i === j && val === 0) val = 1; 
                        mat[i][j] = {n: val, d: 1};
                    }
                }

                // Comprobamos si la matriz se puede resolver por Gauss SIN intercambiar filas
                let temp = JSON.parse(JSON.stringify(mat));
                valid = true;
                for(let p=0; p<detN; p++) {
                    if(fIsZero(temp[p][p])) { valid = false; break; }
                    for(let r=p+1; r<detN; r++) {
                        let factor = fDiv(temp[r][p], temp[p][p]);
                        for(let c=p; c<detN; c++) {
                            temp[r][c] = fSub(temp[r][c], fMul(factor, temp[p][c]));
                        }
                    }
                }
            }
        }

        detMatrix = mat;
        currentPivotCol = 0;
        detUpdateDisplay();
        document.getElementById('det-steps-container').innerHTML = '';
        detRenderStep(0);
    }

    function detUpdateDisplay() {
        let container = document.getElementById('det-matrix-display');
        container.style.gridTemplateColumns = `repeat(${detN}, minmax(45px, auto))`;

        let html = `
            <div style="position: absolute; top: -5px; bottom: -5px; left: 0; width: 4px; border-left: 3px solid #333;"></div>
            <div style="position: absolute; top: -5px; bottom: -5px; right: 0; width: 4px; border-right: 3px solid #333;"></div>
        `;

        for(let i=0; i<detN; i++) {
            for(let j=0; j<detN; j++) {
                html += `<div id="det-m${i}${j}" style="text-align:center;">${formatFracVisual(detMatrix[i][j])}</div>`;
            }
        }
        container.innerHTML = html;
    }

    function detHighlight(pivotCol, targetRow) {
        detUpdateDisplay();
        let piv = document.getElementById(`det-m${pivotCol}${pivotCol}`);
        piv.style.color = "#d35400";
        piv.style.fontWeight = "bold";

        if(targetRow !== null) {
            let targ = document.getElementById(`det-m${targetRow}${pivotCol}`);
            targ.style.color = "#c0392b";
            targ.style.fontWeight = "bold";
        }
    }

    function detHighlightDiagonal() {
        detUpdateDisplay();
        for(let i=0; i<detN; i++) {
            let cell = document.getElementById(`det-m${i}${i}`);
            cell.style.color = "#27ae60";
            cell.style.fontWeight = "bold";
            cell.style.backgroundColor = "#e8f8f5";
            cell.style.borderRadius = "4px";
            cell.style.padding = "2px 5px";
        }
    }

    function detRenderStep(col) {
        rowsCompletedInStep = 0;
        let container = document.getElementById('det-steps-container');

        let box = document.createElement('div');
        box.className = 'det-paso-box';
        // Hacemos el borde izquierdo del color naranja para ser consistentes
        box.style.borderLeftColor = "#d35400";

        let title = `<div style="font-weight: bold; color: #d35400; margin-bottom: 15px; font-size: 1.2em;">Paso ${col+1}: Hacemos ceros en la columna ${col+1}</div>`;
        let rowsHtml = '';

        for(let i = col+1; i < detN; i++) {
            rowsHtml += `
            <div id="step-rowblock-p${col}-r${i}" style="margin-bottom: 20px; padding-bottom: 15px; border-bottom: 1px dashed #eee;">
                <div style="margin-bottom: 10px; font-size: 1.05em;">Pivote = a<sub>${col+1}${col+1}</sub> <span style="color:#666;">| Objetivo: Obtener 0 en a<sub>${i+1}${col+1}</sub></span></div>

                <div style="display: flex; flex-wrap: wrap; gap: 15px; align-items: center;">
                    <div style="background: #fdfdff; padding: 12px; border-radius: 6px; border: 1px dashed #cce0ff;">
                        F<sub>${i+1}</sub> + <input type="text" id="k-r${i}-c${col}" class="det-input-coef"> · F<sub>${col+1}</sub> &rarr; F<sub>${i+1}</sub>
                        <button onclick="checkOp(${i}, ${col})" id="btn-op-r${i}-c${col}" class="det-btn-check" style="margin-left: 10px;">Comprobar Operación</button>
                        <span id="fb-op-r${i}-c${col}" class="det-feedback"></span>
                    </div>

                    <div id="row-result-r${i}-c${col}" style="display: none; align-items: center; gap: 8px; flex-wrap: wrap; margin-top: 10px;">
                        <span style="font-weight:bold; font-size: 1.1em; color: #444;">Nueva F<sub>${i+1}</sub> = (</span>
            `;

            for(let j=0; j<detN; j++) {
                rowsHtml += `<input type="text" id="val-p${col}-r${i}-c${j}" class="det-input-val">`;
            }

            rowsHtml += `
                        <span style="font-weight:bold; font-size: 1.1em; color: #444;">)</span>
                        <button onclick="checkRow(${i}, ${col})" id="btn-row-r${i}-c${col}" class="det-btn-check" style="margin-left: 10px;">Comprobar Fila</button>
                        <span id="fb-row-r${i}-c${col}" class="det-feedback"></span>
                    </div>
                </div>
            </div>`;
        }

        box.innerHTML = title + rowsHtml;
        container.appendChild(box);

        detHighlight(col, col+1);
    }

    function checkOp(targetRow, pivotCol) {
        let kObj = parseFracObj(document.getElementById(`k-r${targetRow}-c${pivotCol}`).value);
        let fb = document.getElementById(`fb-op-r${targetRow}-c${pivotCol}`);

        if(!kObj) { fb.innerHTML = '<span class="det-error">Falta dato</span>'; return; }

        let valTarget = detMatrix[targetRow][pivotCol];
        let valPivot = detMatrix[pivotCol][pivotCol];

        let res = fAdd(valTarget, fMul(kObj, valPivot));

        if (fIsZero(res)) {
            fb.innerHTML = '<span class="det-success">¡Operación válida!</span>';
            document.getElementById(`row-result-r${targetRow}-c${pivotCol}`).style.display = 'flex';
            document.getElementById(`k-r${targetRow}-c${pivotCol}`).disabled = true;
            document.getElementById(`btn-op-r${targetRow}-c${pivotCol}`).style.display = 'none';
        } else {
            fb.innerHTML = '<span class="det-error">La suma no da cero</span>';
        }
    }

    function checkRow(targetRow, pivotCol) {
        let kObj = parseFracObj(document.getElementById(`k-r${targetRow}-c${pivotCol}`).value);
        let fb = document.getElementById(`fb-row-r${targetRow}-c${pivotCol}`);

        let userRow = [];
        for(let j=0; j<detN; j++) {
            let uVal = parseFracObj(document.getElementById(`val-p${pivotCol}-r${targetRow}-c${j}`).value);
            if(!uVal) { fb.innerHTML = '<span class="det-error">Faltan datos en la fila</span>'; return; }
            userRow.push(uVal);
        }

        let isCorrect = true;
        let realRow = [];
        for(let j=0; j<detN; j++) {
            realRow[j] = fAdd(detMatrix[targetRow][j], fMul(kObj, detMatrix[pivotCol][j]));
            if(!fEqual(userRow[j], realRow[j])) isCorrect = false;
        }

        if(isCorrect) {
            fb.innerHTML = '<span class="det-success">¡Fila perfecta!</span>';
            detMatrix[targetRow] = realRow;
            detUpdateDisplay();

            for(let j=0; j<detN; j++) document.getElementById(`val-p${pivotCol}-r${targetRow}-c${j}`).disabled = true;
            document.getElementById(`btn-row-r${targetRow}-c${pivotCol}`).style.display = 'none';

            rowsCompletedInStep++;
            let rowsNeeded = detN - 1 - pivotCol;

            if(rowsCompletedInStep === rowsNeeded) {
                currentPivotCol++;
                if(currentPivotCol === detN - 1) {
                    renderFinalStep();
                } else {
                    detRenderStep(currentPivotCol);
                }
            } else {
                detHighlight(pivotCol, targetRow + 1);
            }
        } else {
            fb.innerHTML = '<span class="det-error">Revisa los cálculos</span>';
        }
    }

    function renderFinalStep() {
        detHighlightDiagonal();
        let container = document.getElementById('det-steps-container');

        let box = document.createElement('div');
        box.style = "width: 100%; max-width: 850px; background: #f8fcfb; border: 2px solid #27ae60; border-radius: 6px; padding: 20px; text-align: center; margin-bottom: 20px; box-shadow: 0 4px 10px rgba(0,0,0,0.05);";

        let html = `
            <h3 style="color: #27ae60; margin-top: 0; font-size: 1.5em;">¡Matriz Triangulada!</h3>
            <p style="margin-bottom: 20px; font-size: 1.1em; color: #444;">El determinante es el producto de los elementos de su diagonal principal.</p>
            <div style="display: inline-flex; align-items: center; gap: 10px; font-size: 1.2em; flex-wrap: wrap; justify-content: center;">
                <b style="color: #27ae60; font-size: 1.2em;">|A| = </b>
        `;

        for(let i=0; i<detN; i++) {
            html += `<input type="text" id="df-diag${i}" class="det-input-val" style="border-color: #27ae60;" placeholder="a${i+1}${i+1}">`;
            if(i < detN-1) html += ` <span style="font-weight: bold;">·</span> `;
        }

        html += `
                <span style="font-weight: bold; margin: 0 10px;">=</span> 
                <input type="text" id="df-final" class="det-input-val" style="width: 70px; background: #e8f8f5; border-color: #27ae60; font-weight: bold;" placeholder="Total">
                <button onclick="checkFinal()" id="btn-final" class="det-btn-check" style="margin-left: 10px; border-color: #27ae60; color: #27ae60;">Comprobar</button>
            </div>
            <div id="res-final" style="margin-top: 15px; font-weight: bold; font-size: 1.2em;"></div>
        `;

        box.innerHTML = html;
        container.appendChild(box);

        // Modificar el estilo del botón final para que tenga "efecto fantasma verde" en el hover
        let btnFinal = document.getElementById('btn-final');
        btnFinal.onmouseover = function() { this.style.backgroundColor = '#27ae60'; this.style.color = '#ffffff'; };
        btnFinal.onmouseout = function() { this.style.backgroundColor = '#ffffff'; this.style.color = '#27ae60'; };
    }

    function checkFinal() {
        let userDiag = [];
        let fb = document.getElementById('res-final');

        for(let i=0; i<detN; i++) {
            let v = parseFracObj(document.getElementById(`df-diag${i}`).value);
            if(!v) { fb.innerHTML = '<span class="det-error">Completa la diagonal</span>'; return; }
            userDiag.push(v);
        }

        let uFinal = parseFracObj(document.getElementById('df-final').value);
        if(!uFinal) { fb.innerHTML = '<span class="det-error">Completa el total</span>'; return; }

        let realDiag = [];
        let realTotal = {n:1, d:1};
        for(let i=0; i<detN; i++) {
            realDiag.push(detMatrix[i][i]);
            realTotal = fMul(realTotal, detMatrix[i][i]);
        }

        let diagMatched = true;
        let used = Array(detN).fill(false);
        for(let i=0; i<detN; i++) {
            let found = false;
            for(let j=0; j<detN; j++) {
                if(!used[j] && fEqual(userDiag[i], realDiag[j])) {
                    used[j] = true; found = true; break;
                }
            }
            if(!found) diagMatched = false;
        }

        if(!diagMatched) {
            fb.innerHTML = '<span class="det-error">Los elementos de la diagonal no coinciden.</span>';
        } else if(!fEqual(realTotal, uFinal)) {
            fb.innerHTML = '<span class="det-error">La multiplicación final no es correcta.</span>';
        } else {
            fb.innerHTML = '<span class="det-success">¡Espectacular! Has calculado el determinante perfectamente. 🎉</span>';
            document.getElementById('btn-final').style.display = 'none';
            for(let i=0; i<detN; i++) document.getElementById(`df-diag${i}`).disabled = true;
            document.getElementById('df-final').disabled = true;
        }
    }

    // Iniciar
    detGenerar();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}
